import numpy as np

def manhattan_distance_transform(mask):
    mask = np.asarray(mask)
    h, w = mask.shape
    INF = h + w
    dt = np.where(mask == 0, 0, INF).astype(np.int32)
    # forward pass: top-left -> bottom-right
    for i in range(h):
        for j in range(w):
            if dt[i, j] == 0:
                continue
            if i > 0:
                dt[i, j] = min(int(dt[i, j]), int(dt[i - 1, j]) + 1)
            if j > 0:
                dt[i, j] = min(int(dt[i, j]), int(dt[i, j - 1]) + 1)
    # backward pass: bottom-right -> top-left
    for i in range(h - 1, -1, -1):
        for j in range(w - 1, -1, -1):
            if i + 1 < h:
                dt[i, j] = min(int(dt[i, j]), int(dt[i + 1, j]) + 1)
            if j + 1 < w:
                dt[i, j] = min(int(dt[i, j]), int(dt[i, j + 1]) + 1)
    return dt
